test.beforeEach(async ({ page, context, browserName }) => {
	if (browserName === 'chromium') await context.grantPermissions(['clipboard-read', 'clipboard-write']);
	await page.bringToFront();
	const observed = { pageErrors: [], consoleErrors: [], failedResponses: [], dialogs: [] }; diagnostics.set(page, observed);
	page.on('pageerror', error => observed.pageErrors.push(error.message));
	page.on('console', message => { if (message.type() === 'error') observed.consoleErrors.push(message.text()); });
	page.on('response', response => {
		if (response.status() >= 400) observed.failedResponses.push({ url: response.url(), status: response.status() });
	});
	page.on('dialog', async dialog => {
		observed.dialogs.push({ type: dialog.type(), message: dialog.message(), boundary: 'browser-owned native dialog' });
		await dialog.dismiss();
	});
});

test.afterEach(async ({ page }, info) => {
	const observed = diagnostics.get(page), path = info.outputPath('browser-diagnostics.json');
	fs.writeFileSync(path, JSON.stringify(observed, null, 2));
	await info.attach('browser-diagnostics', { path, contentType: 'application/json' });
	expect(observed.pageErrors, 'Rendered audit states must not introduce uncaught browser errors').toEqual([]);
});

