async function settled(page) {
	// Fonts, two frames, then every running finite animation finished (finishing one can start another). Waiting on the
	// animations in the page returns as soon as they end; a poll from the test process waits out its interval.
	await page.evaluate(async () => {
		await document.fonts.ready;
		await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
		const deadline = performance.now() + 5000;
		for (;;) {
			const running = document.getAnimations().filter(animation =>
				animation.playState === 'running' && animation.effect?.getTiming().iterations !== Infinity);
			if (!running.length) return;
			const remaining = deadline - performance.now();
			if (remaining <= 0) throw new Error(`${running.length} animation(s) still running after 5 s`);
			await Promise.race([Promise.allSettled(running.map(animation => animation.finished)),
				new Promise(resolve => setTimeout(resolve, Math.min(remaining, 250)))]);
			// The Workbench commits a motion's end state in its finish event, which follows the finished promise.
			await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
		}
	});
}

async function open(page, route, variant, repository = REPOSITORY) {
	await page.setViewportSize({ width: variant.width, height: 1000 });
	if (['server', 'repositories', 'create', 'delete', 'information'].includes(route.split('?')[0])) repository = 'NONE';
	await page.goto(`${WORKBENCH}/repositories/${repository}/${route}`, { waitUntil: 'domcontentloaded' });
	// The page renders before its scripts are mounted; capture and press controls only once the route is ready.
	await waitForRoute(page, route.split('?')[0]);
	await expect(page.locator('#workbench-page-surface')).toBeVisible();
	await expect.poll(() => page.locator('#workbench-page-surface').evaluate(element => element.children.length))
		.toBeGreaterThan(0);
	if (/^(query|update)(?:[?#]|$)/.test(route)) await expect(page.locator('.CodeMirror').first()).toBeVisible();
	await page.evaluate(theme => window.RDF4JWorkbenchTheme.setPreference(theme), variant.theme);
	await settled(page);
}

// This inventory includes hidden controls. Assertions concern rendered edges;
// CSS gaps, margins and padding remain evidence rather than substitutes for them.
function geometry() {
	const rect = element => {
		const box = element.getBoundingClientRect();
		return Object.fromEntries(['left', 'right', 'top', 'bottom', 'width', 'height'].map(key => [key, box[key]]));
	};
	const visible = element => {
		const box = element.getBoundingClientRect(), style = getComputedStyle(element);
		return box.width > 0 && box.height > 0 && style.display !== 'none' && style.visibility !== 'hidden'
			&& !element.closest('[hidden], [inert]') && !element.closest('details:not([open]) > :not(summary)');
	};
	const identify = element => element.getAttribute('id') || `${element.tagName.toLowerCase()}.${element.getAttribute('class') || ''}`;
	const style = element => {
		const value = getComputedStyle(element);
		return Object.fromEntries(['display', 'boxSizing', 'marginTop', 'marginRight', 'marginBottom', 'marginLeft',
			'paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft', 'borderTopWidth', 'borderRightWidth',
			'borderBottomWidth', 'borderLeftWidth', 'rowGap', 'columnGap', 'alignItems', 'alignSelf', 'justifyContent',
			'flexDirection', 'fontSize', 'fontWeight', 'lineHeight', 'whiteSpace', 'overflowX', 'overflowY', 'minHeight']
			.map(key => [key, value[key]]));
	};
	const text = element => {
		const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT), boxes = [];
		let node;
		while ((node = walker.nextNode())) {
			if (!node.textContent.trim() || !visible(node.parentElement)) continue;
			const range = document.createRange(); range.selectNodeContents(node);
			for (const box of range.getClientRects()) boxes.push({ left: box.left, right: box.right, top: box.top, bottom: box.bottom });
		}
		return boxes;
	};
	const controls = Array.from(document.querySelectorAll('button, input:not([type=hidden]), select, textarea, summary, '
		+ 'a[href], [role=button], [role=tab], [role=menuitem], .CodeMirror-hint')).map(element => {
		const outer = element.closest('.workbench-action, .workbench-select-control, .workbench-source-tabs label') || element;
		const label = Array.from(element.labels || []).find(candidate => !candidate.contains(element) && visible(candidate));
		const box = rect(element);
		return { control: identify(element), tag: element.tagName, type: element.type, role: element.getAttribute('role'),
			name: element.getAttribute('aria-label') || element.getAttribute('title') || element.textContent.trim().slice(0, 160)
				|| element.value || element.name || '',
			visible: visible(element), disabled: !!element.disabled || element.getAttribute('aria-disabled') === 'true',
			rect: box, style: style(element), outer: { control: identify(outer), rect: rect(outer), style: style(outer) },
			text: text(element), label: label ? { control: identify(label), rect: rect(label), text: text(label),
				gap: box.top - rect(label).bottom, leftDelta: box.left - rect(label).left } : null };
	});
	const groups = Array.from(document.querySelectorAll('form, section, article, fieldset, .workbench-field, '
		+ '.workbench-form-grid, .workbench-form-actions, .workbench-inline-controls, .workbench-choice-list, '
		+ '.workbench-disclosure, .workbench-disclosure__content, .workbench-disclosure__fields, .workbench-advanced__field, '
		+ '.query-actions-toolbar, .query-actions-toolbar__primary, .query-explanation-toolbar, .query-compare-toolbar, '
		+ '.query-result-toolbar, .query-result-controls, .query-result-pagination, .query-result-navigation, '
		+ '.saved-query-actions, .saved-query-row, .yasqe_buttons, .yasqe_sharePopup, .CodeMirror-hints, table.dataentry tr'))
		.filter(visible).map(element => {
			const children = Array.from(element.children).filter(visible).map(child => ({ control: identify(child), rect: rect(child) }));
			const relationships = children.slice(1).map((after, index) => {
				const before = children[index];
				return { before: before.control, after: after.control, horizontal: after.rect.left - before.rect.right,
					vertical: after.rect.top - before.rect.bottom,
					centerDelta: (after.rect.top + after.rect.bottom - before.rect.top - before.rect.bottom) / 2 };
			});
			return { group: identify(element), rect: rect(element), style: style(element), children, relationships,
				overflow: element.scrollWidth - element.clientWidth };
		});
	return { url: location.href, theme: document.documentElement.dataset.theme, width: innerWidth,
		pageOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
		meaningfulText: document.querySelector('#workbench-page-surface')?.innerText || '', controls, groups };
}

async function capture(page, info, route, state, coverage = 'live backend') {
	await settled(page);
	const measured = await page.evaluate(geometry), label = `${route}-${state}-${measured.width}-${measured.theme}`;
	const name = label.replace(/[^\w.-]/g, '-'), json = info.outputPath(`${name}-geometry.json`), png = info.outputPath(`${name}.png`);
	fs.writeFileSync(json, JSON.stringify({ route, state, coverage, ...measured }, null, 2));
	await info.attach(`${label}-geometry`, { path: json, contentType: 'application/json' });
	// WebKit cannot capture more than 32767 pixels in a dimension; a long page (Explore with every row at 320 px) is
	// then captured as its viewport. The screenshot is evidence only; the assertions use the measured geometry.
	if (evidenceScreenshots()) {
		const pageHeight = await page.evaluate(() => Math.max(document.documentElement.scrollHeight,
			document.body.scrollHeight) * window.devicePixelRatio);
		await page.screenshot({ path: png, fullPage: pageHeight <= 32767, caret: 'hide' });
		await info.attach(`${label}-screenshot`, { path: png, contentType: 'image/png' });
	}
	expect(measured.meaningfulText.trim(), `${label}: the route must have meaningful rendered content`).not.toBe('');
	expect(measured.pageOverflow, `${label}: horizontal overflow must remain in a bounded content region`).toBeLessThanOrEqual(1);
	expect(measured.controls.some(control => control.visible), `${label}: controls must be rendered`).toBe(true);
}

async function reveals(page, info, route) {
	const triggers = await page.locator('#workbench-page-surface button[aria-controls][aria-expanded]').evaluateAll(elements =>
		elements.map(element => ({ id: element.id, panel: element.getAttribute('aria-controls') })).filter(element => element.id));
	for (const trigger of triggers) {
		// Ids such as saved-query URNs contain ':', which a #id selector cannot hold.
		const button = page.locator(`[id="${trigger.id}"]`);
		if (!await button.isVisible()) continue;
		if (await button.getAttribute('aria-expanded') === 'true') await button.click();
		await button.click(); await expect(button).toHaveAttribute('aria-expanded', 'true');
		await expect(page.locator(`[id="${trigger.panel}"]`)).toBeVisible();
		await capture(page, info, route, `open-${trigger.id}`);
		await button.click(); await expect(button).toHaveAttribute('aria-expanded', 'false'); await settled(page);
	}
	const details = page.locator('#workbench-page-surface details');
	for (let index = 0; index < await details.count(); index++) {
		const owner = details.nth(index), summary = owner.locator(':scope > summary');
		if (!await summary.isVisible()) continue;
		if (await owner.evaluate(element => element.open)) await summary.click();
		await summary.click(); await expect(owner).toHaveAttribute('open', '');
		await capture(page, info, route, `details-${index}`); await summary.click();
	}
}

async function navigation(page, info, state) {
	const menuButton = page.locator('#workbench-menu-button');
	const groups = page.locator('#navigation .workbench-nav-group__disclosure');
	for (let index = 0; index < await groups.count(); index++) {
		const group = groups.nth(index), trigger = group.locator(':scope > summary');
		if (await group.evaluate(element => element.open)) await trigger.click();
		await capture(page, info, 'navigation', `${state}-${index}-closed`);
		await trigger.click(); await capture(page, info, 'navigation', `${state}-${index}-open`);
	}
	if (await menuButton.isVisible()) {
		await capture(page, info, 'navigation', `${state}-shell-closed`);
		await menuButton.click(); await capture(page, info, 'navigation', `${state}-shell-open`);
		await page.keyboard.press('Escape');
	}
}

for (const variant of VARIANTS) {
	test(`route and creation controls ${variant.width} ${variant.theme}`, async ({ page }, info) => {
		for (const route of ROUTES) {
			await open(page, route, variant); await capture(page, info, route, 'initial'); await reveals(page, info, route);
			if (route === 'create') {
				const values = await page.locator('#type option').evaluateAll(options => options.map(option => option.value));
				expect(values).toEqual(CREATE_TYPES);
			}
			if (route === 'add') for (const source of ['url', 'text']) {
				await page.locator(`label[for=source-${source}]`).click();
				await capture(page, info, route, `source-${source}`); await reveals(page, info, `add-${source}`);
			}
		}
		for (const type of CREATE_TYPES) {
			await open(page, `create?type=${type}`, variant); await capture(page, info, `create-${type}`, 'required');
			await reveals(page, info, `create-${type}`);
			if (type === 'federate') {
				await page.locator(`input.memberID[value="${REPOSITORY}"]`).check();
				await capture(page, info, 'create-federate', 'one-member');
				await page.locator(`input.memberID[value="${EMPTY}"]`).check();
				await capture(page, info, 'create-federate', 'two-members');
			}
		}
		for (const route of ['summary', 'namespaces', 'contexts', 'types', 'explore', 'export', 'saved-queries']) {
			await open(page, route, variant, EMPTY); await capture(page, info, route, 'empty'); await reveals(page, info, `empty-${route}`);
		}
		await open(page, 'delete', variant, 'NONE');
		await page.locator('[data-workbench-window-action=next]').click();
		await capture(page, info, 'delete', 'picker-next-window');
		await page.locator('[data-workbench-window-action=previous]').click();
		await capture(page, info, 'delete', 'picker-previous-window');
		// Namespaces lists every prefix and filters in the page (M6.3) instead of paging a picker.
		await open(page, 'namespaces', variant, PICKER);
		await page.locator('#namespaces-filter').fill('p1');
		await capture(page, info, 'namespaces', 'filtered');
		for (const resource of ['Class', 'property']) {
			await open(page, `explore?resource=${encodeURIComponent(`<urn:spacing:${resource}>`)}`, variant);
			await page.locator('#explore-result-options-toggle').click(); await page.locator('#limit_explore').selectOption('0');
			await page.locator('#resource').press('Enter');
			// The form shows the next page in place once its model arrived; until then the previous page (default limit)
			// stays on screen with its own paging buttons, so wait for the new page before using them.
			await waitForRoute(page, 'explore', { url: /[?&]limit_explore=0(&|$)/ });
			await expect(page.locator('[data-workbench-explore-action=next]').first()).toBeVisible();
			await capture(page, info, 'explore', `${resource}-all-groups`);
			const groups = await page.locator('[data-workbench-explore-action=next]').evaluateAll(elements =>
				elements.map(element => element.getAttribute('data-workbench-explore-group')));
			for (const group of groups) {
				const previous = page.locator(`[data-workbench-explore-group="${group}"][data-workbench-explore-action=previous]`);
				await page.locator(`[data-workbench-explore-group="${group}"][data-workbench-explore-action=next]`).click();
				// A group's next page renders after its rows are read; Previous is enabled once it is shown.
				await expect(previous).toBeEnabled();
				await capture(page, info, 'explore', `${group}-next`);
				await previous.click();
			}
		}
		await open(page, 'query', variant); await navigation(page, info, 'configured');
	});
}

async function setQuery(page, value) {
	await page.locator('#query-primary-pane .CodeMirror').evaluate((element, query) => element.CodeMirror.setValue(query), value);
}

async function execute(page, value) {
	await setQuery(page, value); await page.locator('#exec').click();
	const result = page.locator('#query-results [data-query-stream-root]');
	await expect(result).toBeVisible(); await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	return result;
}

for (const variant of VARIANTS) {
	test(`query output controls ${variant.width} ${variant.theme}`, async ({ page }, info) => {
		await open(page, 'query', variant);
		// The query result has no result limit, page size or Next/Previous paging any more: Execute streams every row
		// and "Load more" continues past a million (design/workbench-loadmore-20260930/handoff.md), so the long result
		// is measured whole.
		const result = await execute(page, 'SELECT ?s ?o WHERE { ?s <urn:spacing:p> ?o } ORDER BY ?s');
		await expect(result.locator('.query-result-status')).toContainText('120 rows');
		await capture(page, info, 'query', 'tuple-long'); await reveals(page, info, 'query-result');
		await result.locator('[id^=query-result-options-toggle-]').click();
		await result.locator('[id^=result-layout-]').selectOption('records'); await capture(page, info, 'query', 'records');
		await result.locator('[id^=result-wrap-values-]').uncheck(); await capture(page, info, 'query', 'unwrapped-records');
		await result.locator('[id^=show-datatypes-]').uncheck(); await capture(page, info, 'query', 'no-datatypes');
		// Full screen is the result's own toolbar button (the page-level #query-results-fullscreen stays hidden).
		const fullscreen = result.locator('[id^=query-result-fullscreen-]');
		await fullscreen.click(); await expect(fullscreen).toHaveAttribute('aria-pressed', 'true');
		await capture(page, info, 'query', 'result-fullscreen');
		await fullscreen.click(); await expect(fullscreen).toHaveAttribute('aria-pressed', 'false');
		for (const [state, query] of [['empty', 'SELECT ?s WHERE { VALUES ?s {} }'],
			['boolean-no', 'ASK { <urn:absent> ?p ?o }'], ['boolean-yes', 'ASK { ?s ?p ?o }'],
			['graph', 'CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o } LIMIT 10'], ['syntax-error', 'SELECT WHERE {']]) {
			await open(page, 'query', variant); await execute(page, query);
			await capture(page, info, 'query', state); await reveals(page, info, state);
		}
		await open(page, 'query', variant); await setQuery(page, 'SELECT ?s WHERE { ?s ?p ?o }');
		let release;
		const blocked = new Promise(resolve => { release = resolve; });
		let abortedRequest;
		await page.route('**/query', async route => {
			if (route.request().headers().accept?.includes('application/vnd.rdf4j.workbench+ndjson')) {
				abortedRequest = (async () => { await blocked; await route.abort(); })();
				await abortedRequest;
			} else await route.continue();
		});
		try {
			const request = page.waitForRequest(request => request.headers().accept?.includes('application/vnd.rdf4j.workbench+ndjson'));
			await page.locator('#exec').click(); await request;
			await expect(page.locator('#query-results-loading')).toBeVisible();
			await capture(page, info, 'query', 'loading', 'controlled delay of real query request');
			await page.locator('#query-cancel').click(); await capture(page, info, 'query', 'cancelled');
		} finally {
			release();
			// Drain the owned request before the page fixture closes. Toggling Firefox
			// interception off on this already-cancelled channel raises NS_BINDING_ABORTED.
			if (abortedRequest) await abortedRequest;
		}
	});
}

async function renderFixture(page, viewId, workbench, metadata = {}, repositoryId = REPOSITORY) {
	await page.evaluate(({ viewId, workbench, metadata, repositoryId }) => {
		const app = document.querySelector('#workbench-app'), mount = document.createElement('div');
		app.replaceChildren(mount);
		window.workbench.views.render(mount, { viewId, vars: [], rows: [], rowCount: 0, rowStart: 0,
			pickerRows: [], pickerStart: 0, pickerPageSize: 50, metadata, namespaceMap: {}, links: [],
			rowTopSpacer: 0, rowBottomSpacer: 0 },
		{ basePath: '/rdf4j-workbench', repositoryId, workbench }, window.RDF4JLitHTML);
	}, { viewId, workbench, metadata, repositoryId });
	await settled(page);
}

