		await open(page, 'saved-queries', variant);
		const card = page.locator('.saved-query-row').filter({ has: page.locator(`.saved-query-delete[data-query-name="${name}"]`) });
		await expect(card).toBeVisible(); savedUrns.add(await card.locator('.saved-query-delete').getAttribute('data-query-urn'));
		await capture(page, info, 'saved-queries', 'before-execution');
