for (const width of [1440, 320]) for (const theme of ['light', 'dark']) {
	test(`conditional renderer controls ${width} ${theme}`, async ({ page }, info) => {
		await open(page, 'information', { width, theme }); await renderFixture(page, 'information', {});
		// Without menu metadata the shell renders no menu (the fallback menu was removed, and menu groups are
		// never disclosures: plan workbench-app-shell-and-critique-fixes-20260930, M2.1 and M2.4).
		await expect(page.locator('#navigation .workbench-nav-group')).toHaveCount(0);
		await expect(page.locator('#navigation .workbench-nav-group__disclosure')).toHaveCount(0);
		await navigation(page, info, 'absent-menu-fallback');
		await renderFixture(page, 'information', { menu: [] });
		await capture(page, info, 'navigation', 'empty-menu-policy', 'actual renderer with explicit empty menu');
		await expect(page.locator('#navigation .workbench-nav-group__disclosure')).toHaveCount(0);
		await renderFixture(page, 'information', { readable: false, writeable: false });
		await capture(page, info, 'navigation', 'restricted-policy', 'actual renderer with legal read/write policy');
		const features = Object.fromEntries(FEATURES.map(feature => [feature, false]));
		await renderFixture(page, 'query', { queryFeatures: features });
		await capture(page, info, 'query', 'disabled-actions', 'actual renderer with legal disabled feature metadata');
		await expect(page.locator('#exec')).not.toBeVisible();
		for (const kind of ['tuple', 'graph']) {
			await renderFixture(page, 'query', { queryFeatures: features });
			await page.evaluate(async ({ kind, features }) => {
				const target = document.getElementById('query-results'); target.hidden = false;
				const renderer = new window.workbench.queryStream.QueryResultRenderer(target, { features });
				await renderer.accept({ type: 'view', id: `query-result-${kind}` });
				await renderer.accept({ type: 'vars', values: kind === 'tuple' ? ['value'] : ['subject', 'predicate', 'object', 'context'] });
				await renderer.accept({ type: 'rows', values: [kind === 'tuple' ? [{ kind: 'literal', value: 'Owned tuple value' }]
					: [{ kind: 'iri', value: 'urn:s' }, { kind: 'iri', value: 'urn:p' }, { kind: 'literal', value: 'Owned graph value' }, null]] });
				await renderer.accept({ type: 'end', metadata: {} });
			}, { kind, features });
			await capture(page, info, 'query', `${kind}-disabled-controls`, 'actual public renderer with legal records/features');
			await expect(page.locator('.query-result-options-toggle')).not.toBeVisible();
		}
		for (const route of ['add', 'remove', 'clear', 'update', 'explore', 'namespaces', 'server']) {
			await renderFixture(page, route, { defaults: { 'default-Content-Type': 'text/turtle' },
				uploadFormats: [{ value: 'text/turtle', label: 'Turtle' }] },
			{ 'error-message': `Owned rendered invalid RDF error ${'urn:invalid:'.repeat(30)}` });
			await capture(page, info, route, 'legal-error-model', 'actual renderer; live error propagation remains separately limited');
		}
		for (const route of ['add', 'remove', 'clear']) {
			await renderFixture(page, route, {}, {}, 'SYSTEM');
			await capture(page, info, route, 'system-warning', 'actual renderer; SYSTEM data is not mutated');
		}
	});
}
